// Mesh coverage index — record JAH-GPCS-MESHNODE-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"coverage_sqft": 6000, "speed_mbps": 5400, "price_usd": 400};
var value = (m.coverage_sqft*m.speed_mbps/m.price_usd/1000);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-MESHNODE-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-MESHNODE-000001|' + value.toFixed(2) + ' coverage index');

